/* ZEE — interface V2. Gráficos Plotly provisórios, com paleta configurável. */
const data = __DATA__;
const $ = id => document.getElementById(id);
const el = (name, cls, text) => { const node = document.createElement(name); if (cls) node.className = cls; if (text !== undefined) node.textContent = String(text); return node; };
const fmt = n => Number(n).toLocaleString('pt-BR');
const chartColors={daily:'#05B70B',minute:'#DEBD00',tags:'#0088DC'};
const chartFont='SF Pro, SF Pro Display, -apple-system, Segoe UI, Arial, sans-serif';
const allMinutes = Array.from({length: 1440}, (_,i) => `${String(Math.floor(i/60)).padStart(2,'0')}:${String(i%60).padStart(2,'0')}`);
const plotConfig = {displaylogo:false,responsive:true};
const minuteLayout = {paper_bgcolor:'#f6f6f6',plot_bgcolor:'#f6f6f6',margin:{l:52,r:18,t:18,b:56},xaxis:{title:'Horário (HH:mm)',type:'category',tickmode:'array',tickvals:['00:00','03:00','06:00','09:00','12:00','15:00','18:00','21:00','23:59'],rangeslider:{visible:true},showgrid:false,zeroline:false,linecolor:'#aaa'},yaxis:{title:'Postagens por minuto',rangemode:'tozero',gridcolor:'#dedede',zeroline:false},font:{family:chartFont,color:'#222'},autosize:true,showlegend:false};
function plotMinute(id,date,hour='all'){
  const map=data.minute[date]||{};
  // Filtro por horário somente na Timeline. Cada ponto continua representando um minuto real.
  const times=hour==='all'?allMinutes:allMinutes.slice(Number(hour)*60,(Number(hour)+1)*60);
  const values=times.map(t=>map[t]||0);
  const hourly=hour!=='all';
  const ticks=hourly?[0,15,30,45,59].map(i=>times[i]):minuteLayout.xaxis.tickvals;
  const layout={...minuteLayout,xaxis:{...minuteLayout.xaxis,tickvals:ticks,rangeslider:{visible:!hourly}},uirevision:'minute-'+id+'-'+date+'-'+hour};
  return Plotly.react(id,[{type:'scatter',mode:'lines',x:times,y:values,line:{color:chartColors.minute,width:2.5},fill:'tozeroy',fillcolor:'rgba(222,189,0,.09)',hovertemplate:date+' %{x}<br><b>%{y}</b> postagens<extra></extra>'}],layout,plotConfig);
}
function resizeCharts(selector){requestAnimationFrame(()=>{document.querySelectorAll(selector+' .js-plotly-plot').forEach(g=>{const rect=g.getBoundingClientRect();if(rect.width>0&&rect.height>0)Plotly.Plots.resize(g);});});}
function switchTab(name){document.querySelectorAll('.tab').forEach(e=>e.classList.toggle('active',e.id===name));document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===name;b.classList.toggle('active',active);active?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current')});resizeCharts('#'+name);}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));
const defaultDay=data.default_day||data.available_days[0]||'';
for(const id of ['day','overviewDay']){const select=$(id);for(const d of data.available_days){const option=el('option','',d);option.value=d;select.appendChild(option);}select.value=defaultDay;}
// O horário detalha a série por minuto sem alterar os dados originais do Python.
const timelineHour=$('timelineHour');
const allHours=el('option','','Dia inteiro');allHours.value='all';timelineHour.append(allHours);
for(let h=0;h<24;h++){
  const option=el('option','',`${String(h).padStart(2,'0')}:00 – ${String(h).padStart(2,'0')}:59`);
  option.value=String(h);timelineHour.append(option);
}
timelineHour.value='all';
function renderTimelineMinute(){return plotMinute('minuteChart',$('day').value,timelineHour.value);}
$('day').addEventListener('change',renderTimelineMinute);
timelineHour.addEventListener('change',renderTimelineMinute);
function switchTimelineScale(minute){
  $('timelineDailyChart').classList.toggle('hidden',minute);
  $('minuteChart').classList.toggle('hidden',!minute);
  $('timelineMinuteFilters').hidden=!minute;
  $('timelineMinuteNote').hidden=!minute;
  $('timelineDailyButton').setAttribute('aria-pressed',String(!minute));
  $('timelineMinuteButton').setAttribute('aria-pressed',String(minute));
  $('timelineHeading').textContent=minute?'Volume de dados por minuto':'Volume de dados por dia';
  if(minute)renderTimelineMinute();
  else resizeCharts('#timelineDailyChart');
  requestAnimationFrame(()=>requestAnimationFrame(fitVisibleCharts));
}
$('timelineDailyButton').addEventListener('click',()=>switchTimelineScale(false));
$('timelineMinuteButton').addEventListener('click',()=>switchTimelineScale(true));
$('overviewDay').addEventListener('change',()=>{if(!$('overviewMinuteChart').classList.contains('hidden'))plotMinute('overviewMinuteChart',$('overviewDay').value)});
// A Timeline inicia no gráfico diário; o gráfico por minuto é desenhado ao ser selecionado.
function switchOverviewScale(minute){$('overviewDailyChart').classList.toggle('hidden',minute);$('overviewMinuteChart').classList.toggle('hidden',!minute);$('overviewDailyButton').setAttribute('aria-pressed',String(!minute));$('overviewMinuteButton').setAttribute('aria-pressed',String(minute));if(minute)plotMinute('overviewMinuteChart',$('overviewDay').value);else resizeCharts('#overviewDailyChart');}
$('overviewDailyButton').addEventListener('click',()=>switchOverviewScale(false));
$('overviewMinuteButton').addEventListener('click',()=>switchOverviewScale(true));
const posts=data.posts||[];
$('postsTotal').textContent=fmt(posts.length)+' publicações ranqueadas';
$('postsCount').textContent=fmt(posts.length);
if(!posts.length)$('postList').append(el('div','empty','Nenhuma publicação com contagens válidas.'));
const postAvatarDataURI='data:image/svg+xml;base64,';
// Os dados atuais fornecem p.author como identificador; o nome de exibição é opcional.
// Quando o ZEE passar a exportá-lo, usar p.author_fullname ou p.display_name.
const postIcon=(name)=>{
  const paths={
    likes:'M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78Z',
    reposts:'M17 2l4 4-4 4 M3 11V9a3 3 0 0 1 3-3h15 M7 22l-4-4 4-4 M21 13v2a3 3 0 0 1-3 3H3',
    replies:'M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z'
  };
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
  svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('width','17');svg.setAttribute('height','17');
  svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.7');
  svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');
  const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',paths[name]);svg.append(path);
  return svg;
};
// Cards de publicação: layout aprovado no laboratório visual (v3).
// Nome de exibição opcional: somente usar quando o Python passar a fornecê-lo.
for(const [i,p] of posts.entries()){
  const card=el('article','post post-card');
  const ranking=el('div','post-ranking');
  ranking.append(el('strong','post-rank',`${i+1}º`),el('span','post-score',fmt(p.score)+' interações'));
  card.append(ranking);

  const top=el('div','post-top');
  const avatar=el('img','post-avatar');
  avatar.src=postAvatarDataURI;avatar.alt='';avatar.width=54;avatar.height=54;
  const identity=el('div','post-user');
  const handle='@'+String(p.author||'sem autor').replace(/^@/,'');
  const displayName=String(p.author_fullname||p.display_name||'').trim();
  if(displayName)identity.append(el('strong','post-display-name',displayName));
  identity.append(el('span','post-handle',handle));
  top.append(avatar,identity);card.append(top);

  const body=el('p','post-body',p.body||'(sem texto)');
  body.title=p.body||'';card.append(body);
  if(p.datetime){
    const time=el('time','post-datetime',p.datetime);
    time.dateTime=p.datetime;card.append(time);
  }
  card.append(el('div','post-divider'));

  const stats=el('div','post-stats');
  for(const [name,label,value] of [
    ['likes','Curtidas',p.likes],['reposts','Repostagens',p.reposts],['replies','Respostas',p.replies]
  ]){
    const stat=el('span','post-stat');stat.title=label;
    stat.append(postIcon(name),el('span','',fmt(value||0)));stats.append(stat);
  }
  card.append(stats);
  const footer=el('div','post-footer');
  if(/^https:\/\/(?:www\.)?(?:x\.com|twitter\.com)\//i.test(p.link||'')){
    const link=el('a','post-link','Link para publicação ↗');
    link.href=p.link;link.target='_blank';link.rel='noopener noreferrer';
    link.setAttribute('aria-label','Abrir publicação de '+handle+' no X');
    footer.append(link);
  }else{
    footer.append(el('span','post-link post-link-unavailable','Link indisponível'));
  }
  card.append(footer);$('postList').append(card);
}
function showTags(){const q=$('tagSearch').value.trim().toLocaleLowerCase('pt-BR');const filtered=(data.tags||[]).filter(t=>t[0].toLocaleLowerCase('pt-BR').includes(q));$('tagsTotal').textContent=fmt(filtered.length)+' hashtags encontradas';const list=$('tagList');list.replaceChildren();const max=(data.tags||[]).length?data.tags[0][1]:1;
 for(const [i,[tag,quantity]] of filtered.slice(0,200).entries()){const row=el('div','tag-row');const name=el('div','tag-name');name.append(el('span','tag-rank',`${i+1}º`),document.createTextNode(tag));const bar=el('div','bar');const fill=el('div','bar-fill');fill.style.width=(100*quantity/max)+'%';bar.append(fill);row.append(name,bar,el('div','tag-value',fmt(quantity)));list.append(row);}
 if(filtered.length>200)list.append(el('p','muted','Exibindo as 200 primeiras hashtags filtradas. Refine sua busca para localizar outras.'));
 if(!filtered.length)list.append(el('p','empty','Nenhuma hashtag encontrada.'));
}
$('tagSearch').addEventListener('input',showTags);showTags();
const dialogs={method:{title:'Metodologia',body:'Os resultados são calculados exclusivamente a partir do CSV analisado. Publicações com identificador repetido são contadas uma vez. O ranking de postagens utiliza soma_count, quando disponível, ou a soma de curtidas, respostas e repostagens. A série temporal utiliza a data de publicação no fuso escolhido; dias sem ocorrências no intervalo recebem zero. Hashtags são extraídas apenas da coluna específica.'},about:{title:'Sobre o ZEE',body:'ZEE é uma ferramenta de exploração dos dados exportados pelo Zeeschuimer para Twitter/X. O dashboard apresenta o corpus observado, sem representar necessariamente a totalidade da plataforma. As informações de auditoria e os parâmetros da execução estão nos arquivos de relatório produzidos com o dashboard.'}};
function showDialog(key){const info=dialogs[key];if(!info)return;$('dialogTitle').textContent=info.title;$('dialogBody').replaceChildren(el('p','',info.body));$('infoDialog').classList.add('open');$('dialogClose').focus();}
function closeDialog(){$('infoDialog').classList.remove('open');}
$('dialogClose').addEventListener('click',closeDialog);$('infoDialog').addEventListener('click',e=>{if(e.target===$('infoDialog'))closeDialog()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDialog()});
// Navegação principal utiliza links reais para as seções do site.



/* Mantém os gráficos Plotly incluídos pelo Python, atualizando apenas a aparência.
   Os dados e a criação do HTML continuam sob responsabilidade do ZEE. */
function recolorDaily() {
  for (const root of [document.getElementById('overviewDailyChart'), document.getElementById('timelineDailyChart')]) {
    if (!root) continue;
    const graph=root.querySelector('.js-plotly-plot');
    if (!graph || !graph.data) continue;
    Plotly.restyle(graph, {'line.color':chartColors.daily,'fillcolor':'rgba(5,183,11,.08)'});
    Plotly.relayout(graph, {'font.family':chartFont});
  }
}
function fitVisibleCharts() {
  for (const graph of document.querySelectorAll('.tab.active .js-plotly-plot')) {
    const box=graph.closest('.graphbox');
    if (!box || box.classList.contains('hidden')) continue;
    const boxRect=box.getBoundingClientRect();
    if (boxRect.height<=0 || boxRect.width<=0 || graph.getClientRects().length===0) continue;
    const height=Math.max(120, Math.round(boxRect.height));
    const width=Math.max(220, Math.round(boxRect.width));
    if (Math.abs((graph.layout?.height||0)-height)>3 || Math.abs((graph.layout?.width||0)-width)>3) {
      Plotly.relayout(graph,{height,width,autosize:false});
    } else {
      Plotly.Plots.resize(graph);
    }
  }
}
const _originalSwitchTab=switchTab;
switchTab=function(name){_originalSwitchTab(name);requestAnimationFrame(()=>requestAnimationFrame(fitVisibleCharts));};
const _originalOverviewScale=switchOverviewScale;
switchOverviewScale=function(minute){_originalOverviewScale(minute);requestAnimationFrame(()=>requestAnimationFrame(fitVisibleCharts));};
if ('ResizeObserver' in window) {
  const chartsObserver=new ResizeObserver(()=>requestAnimationFrame(fitVisibleCharts));
  document.querySelectorAll('.chart-panel .graph-area').forEach(box=>chartsObserver.observe(box));
}
window.addEventListener('resize',()=>requestAnimationFrame(fitVisibleCharts));
recolorDaily();
requestAnimationFrame(()=>requestAnimationFrame(fitVisibleCharts));
